	void noteGenerationWork(String label) {
		if (label == null || label.isEmpty()) {
			return;
		}
		Integer seen = generationActivity.get(label);
		generationActivity.put(label, Integer.valueOf(seen == null ? 1 : seen.intValue() + 1));
		if (generationStack.size() < 64) {
			generationStack.addLast(label);
		}
	}

